(() => {
  const dialogs = document.querySelectorAll('[role="dialog"]');
  let out = [];
  dialogs.forEach((d, i) => {
    // find checkboxes
    const checkboxes = d.querySelectorAll('input[type="checkbox"]');
    checkboxes.forEach(cb => {
      out.push({dialog: i, id: cb.id, checked: cb.checked, labelText: cb.parentElement?.innerText || document.querySelector(`label[for="${cb.id}"]`)?.innerText});
    });
    // find elements mentioning 'time range'
    d.querySelectorAll('*').forEach(el => {
      if (el.children.length === 0 && el.innerText && el.innerText.toLowerCase().includes('time range')) {
        out.push({dialog: i, tag: el.tagName, text: el.innerText});
      }
    });
  });
  return JSON.stringify(out);
})()

