(() => {
  // Find the tags section in settings
  const all = Array.from(document.querySelectorAll('*'));
  const tagLabel = all.filter(el => el.children.length === 0 && el.innerText && el.innerText.trim() === 'Tags');
  if (!tagLabel.length) return JSON.stringify({found: false});
  const container = tagLabel[0].closest('div,section,fieldset');
  return JSON.stringify({found: true, text: container ? container.innerText.slice(0, 300) : null});
})()

