(() => {
  // Get the parent chain context of the 'bench' span to confirm it's a tag chip in the Tags field
  const el = Array.from(document.querySelectorAll('span')).find(s => s.innerText.trim() === 'bench' && !s.children.length);
  if (!el) return 'not found';
  let chain = [];
  let cur = el;
  for (let i = 0; i < 6; i++) {
    cur = cur.parentElement;
    if (!cur) break;
    chain.push({cls: String(cur.className).slice(0,80), text: cur.innerText.slice(0,100)});
  }
  // also check siblings
  const sibs = Array.from(el.parentElement.children).map(c => c.innerText.trim());
  return JSON.stringify({chain, siblings: sibs});
})()

